// "22" -> 22. Anything that is not a positive whole number -> null.
export function parseRetryAfter(value) {
  const seconds = Number.parseInt(value, 10)
  return Number.isFinite(seconds) && seconds > 0 ? seconds : null
}

// The backend puts its message in `detail`: a string, or (for invalid input) a list of problems.
function detailText(detail) {
  if (typeof detail === 'string') return detail
  if (Array.isArray(detail) && typeof detail[0]?.msg === 'string') return detail[0].msg
  return null
}

// axios error -> ApiError
export function toApiError(error) {
  if (error instanceof ApiError) return error

  const response = error?.response
  if (!response) {
    // No answer at all: the backend is down, VITE_API_URL is wrong, or the browser blocked the call (CORS).
    return new ApiError('Cannot reach the server. Check that the backend is running.', { code: 'network' })
  }

  const { status, data, headers } = response
  return errorFromStatus(status, data?.detail, headers?.['retry-after'])
}

// An HTTP error status (+ the backend's `detail` and the Retry-After header) -> ApiError. Shared by axios calls and
// the streaming chat call (fetch).
export function errorFromStatus(status, rawDetail, retryAfterHeader) {
  const detail = detailText(rawDetail)

  if (status === 401) return new ApiError('Your session has expired. Please sign in again.', { status, code: 'auth' })
  if (status === 404) return new ApiError(detail || 'Not found.', { status, code: 'not_found' })
  if (status === 413) return new ApiError('That file is too large (20 MB maximum).', { status, code: 'too_large' })
  if (status === 422) return new ApiError(detail || 'Some of the information is not valid.', { status, code: 'validation' })
  if (status === 429) {
    return new ApiError(detail || 'Too many requests. Please slow down.', {
      status,
      code: 'rate_limited',
      retryAfter: parseRetryAfter(retryAfterHeader),
    })
  }
  if (status >= 500) return new ApiError(detail || 'The server had a problem. Please try again.', { status, code: 'server' })
  return new ApiError(detail || `The request failed (${status}).`, { status })
}

export async function askStream({ query, conversationId, onToken, signal }) {
  const token = await getAuthToken()
  let response
  try {
    response = await fetch(`${api.defaults.baseURL}/ask/stream`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        ...(token ? { Authorization: `Bearer ${token}` } : {}),
      },
      body: JSON.stringify({ query, conversation_id: conversationId ?? null }),
      signal,
    })
  } catch (error) {
    if (error.name === 'AbortError') throw error
    throw new ApiError('Cannot reach the server. Check that the backend is running.', { code: 'network' })
  }

  if (!response.ok) {
    let body = null
    try {
      body = await response.json()
    } catch {
      /* not JSON */
    }
    throw errorFromStatus(response.status, body?.detail, response.headers.get('retry-after'))
  }

  const reader = response.body.getReader()
  const decoder = new TextDecoder()
  let buffer = ''
  let done = null

  for (;;) {
    const { value, done: finished } = await reader.read()
    if (finished) break
    buffer += decoder.decode(value, { stream: true })
    // events are separated by a blank line; keep an unfinished one in the buffer
    let boundary
    while ((boundary = buffer.indexOf('\n\n')) !== -1) {
      const block = buffer.slice(0, boundary)
      buffer = buffer.slice(boundary + 2)
      const event = parseEvent(block)
      if (!event) continue
      if (event.type === 'token') onToken?.(event.data.text ?? '')
      else if (event.type === 'done') done = event.data
      else if (event.type === 'error') throw errorFromStatus(event.data.status ?? 500, event.data.detail)
    }
  }

  if (!done) throw new ApiError('The answer was cut off. Please try again.', { code: 'server' })
  return done
}

// "event: token\ndata: {...}" -> { type, data }
function parseEvent(block) {
  let type = 'message'
  const data = []
  for (const line of block.split('\n')) {
    if (line.startsWith('event:')) type = line.slice(6).trim()
    else if (line.startsWith('data:')) data.push(line.slice(5).trimStart())
  }
  if (!data.length) return null
  try {
    return { type, data: JSON.parse(data.join('\n')) }
  } catch {
    return null
  }
}

def _describe(facts: list[SelfFact]) -> str:
    phrases = []
    for f in facts:
        if f.kind == "role":
            phrases.append(f"are {'an' if f.value[:1].lower() in 'aeiou' else 'a'} {f.value}")
        elif f.kind == "workplace":
            phrases.append(f"work {'in' if f.text.startswith('Works in') else 'at'} {f.value}")
        elif f.kind == "preference":
            phrases.append(f"prefer {f.value}")
    return " and ".join(phrases)

