    }
    return mode === 'code'
      ? 'This file type is not supported in a Codebase chat. Use source code (.py, .js, .ts, .java, .c, .cpp), Markdown or text.'
      : 'This file type is not supported. Use PDF, Word, PowerPoint, Excel, CSV, text, Markdown or HTML.'
  }
